<?php
namespace App\Console\Commands;use App\Services\DevOps\ReleaseService;use Illuminate\Console\Command;
final class DevOpsReleasesCommand extends Command {protected $signature='zigo:devops-releases {--environment=} {--json}';protected $description='Lista releases sin modificar datos.';public function handle(ReleaseService $service):int{$e=$this->option('environment');if($e&&!in_array($e,['stage','production'],true))return self::INVALID;$rows=$service->history($e?:null)->limit(100)->get()->map(fn($r)=>['id'=>$r->id,'environment'=>$r->environment,'deployment_id'=>$r->deployment_id,'status'=>$r->status,'branch'=>$r->branch,'commit_hash'=>$r->commit_hash,'package_sha256'=>$r->package_sha256,'files_fingerprint'=>$r->files_fingerprint,'deployed_at'=>$r->deployed_at])->all();if($this->option('json'))$this->line(json_encode($rows,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES));else$this->table(['id','environment','deployment','status','branch','commit','sha','fingerprint','date'],array_map('array_values',$rows));return self::SUCCESS;}}
